<?php
// Local route/contact/document-responsibility tests. No mail or maps network calls.
define('WP_ADMIN',true);require '/var/www/html/wp-load.php';if(wp_parse_url(home_url(),PHP_URL_HOST)!=='127.0.0.1')exit(2);
use VPM\Booking\DB;use VPM\Booking\Core;use VPM\Booking\Logistics;use VPM\Booking\Config;use VPM\Booking\Customer;use VPM\Booking\Tenants;
global $wpdb;$tables=$wpdb->get_col($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->prefix.'vpm_booking_%'));foreach($tables as $t)if($wpdb->get_var("SELECT COUNT(*) FROM $t"))throw new Exception('Nonempty tables refused');$users=[];$checks=[];
function lcheck($v,$s){global $checks;if(!$v)throw new Exception($s);$checks[]=$s;}function lreject($f,$code){try{$f();}catch(Throwable $e){lcheck($e->getMessage()===$code,'reject:'.$code);return;}throw new Exception('Expected '.$code);}
add_filter('pre_http_request',function(){return new WP_Error('blocked_fixture');});add_filter('pre_wp_mail','__return_true');wp_set_current_user(1);
try{
 $p=Core::partner(['airport'=>'STR','name'=>'Location fixture A','stripe_account'=>'acct_locationfixture','commission_bps'=>2000]);$other=Core::partner(['airport'=>'FRA','name'=>'Location fixture B','stripe_account'=>'acct_locationother','commission_bps'=>2000]);
 $profile=['support_phone'=>'+49 000 1234567','billing_email'=>'billing-partner@example.invalid','booking_email'=>'operations-partner@example.invalid','points'=>[]];
 foreach(['parking','handover','return']as $key)$profile['points'][$key]=['name_de'=>'Test '.$key,'name_en'=>'Test '.$key,'address'=>'Testadresse '.$key,'latitude'=>'48,69','longitude'=>'9.19','instructions_de'=>"Testhinweis\nNur lokale Testdaten.",'instructions_en'=>'Local test instructions.'];
 Logistics::save((int)$p['id'],$profile);$stored=Logistics::get((int)$p['id']);lcheck(count($stored['points'])===3&&$stored['points']['handover']['latitude']===48.69,'Three separate places and decimal-comma GPS pin saved');
 $bad=$profile;$bad['points']['handover']['latitude']='91';lreject(function()use($p,$bad){Logistics::save((int)$p['id'],$bad);},'invalid_coordinate');
 $bad=$profile;$bad['points']['handover']['longitude']='';lreject(function()use($p,$bad){Logistics::save((int)$p['id'],$bad);},'coordinate_pair_required');
 $link=Logistics::directions($stored['points']['handover']);lcheck(str_starts_with($link,'https://www.google.com/maps/dir/?api=1&destination=')&&!str_contains($link,'<'),'Directions URL uses fixed Maps host and encoded destination');
 lcheck(str_contains(Logistics::directions(['address'=>'Street & Gate 2']),'Street%20%26%20Gate%202'),'Address-only directions encode special characters');
 $u=wp_insert_user(['user_login'=>'logistics_viewer_'.bin2hex(random_bytes(3)),'user_pass'=>bin2hex(random_bytes(20)),'role'=>'vpm_partner']);$users[]=$u;Tenants::assign((int)$p['id'],(int)$u,'viewer');wp_set_current_user($u);lreject(function()use($p,$profile){Logistics::save((int)$p['id'],$profile);},'portal_forbidden');wp_set_current_user(1);
 $b=Core::create(['partner_id'=>(int)$p['id'],'base_cents'=>10000,'email'=>'location-customer@example.invalid'],'location-booking-fixture');$q=Core::snapshot($b);
 lcheck($q['partner_service']['document_issuer']==='partner'&&$q['partner_service']['cancellation_responsible']==='partner','Booking fixes partner responsibility for documents and cancellations');
 lcheck(Logistics::customer_data($b)['points']===[],'Unconfirmed enquiry does not receive final travel instructions');
 $profile['points']['handover']['address']='New test address';Logistics::save((int)$p['id'],$profile);lcheck(Core::snapshot(Core::booking($b['public_id']))['partner_service']['points']['handover']['address']==='Testadresse handover','Changing partner settings never silently rewrites existing booking');
 Core::confirm($b['public_id']);DB::update('bookings',['payment_state'=>'paid','stripe_pi'=>'pi_locationfixture'],['id'=>$b['id']]);Core::confirm($b['public_id']);$b=Core::booking($b['public_id']);
 $email=$wpdb->get_row('SELECT payload FROM '.DB::table('outbox')." WHERE topic='booking.confirmed'",ARRAY_A);$payload=Config::open($email['payload']);lcheck($payload['recipient']==='location-customer@example.invalid'&&$payload['sender_role']==='platform'&&count($payload['partner_service']['points'])===3,'Customer confirmation envelope carries platform sender role, support and all places');
 lcheck(!str_contains(wp_json_encode($payload['partner_service']),'billing-partner')&&!str_contains(wp_json_encode($payload['partner_service']),'operations-partner'),'Customer-facing service data hides internal partner email addresses');
 $invoice=$wpdb->get_row('SELECT payload FROM '.DB::table('outbox')." WHERE topic='partner.invoice_required'",ARRAY_A);$invoice=Config::open($invoice['payload']);lcheck($invoice['recipient']==='billing-partner@example.invalid'&&$invoice['document_issuer']==='partner','Invoice request routed to partner, not customer invoice generation');
 $access=Customer::issue($b);parse_str(wp_parse_url($access['url'],PHP_URL_FRAGMENT),$f);$view=Customer::view($f['token']);lcheck(count($view['partner_service']['points'])===3&&$view['partner_service']['support_phone']===$profile['support_phone'],'Private customer view exposes confirmed routes and partner phone');
 Customer::cancellation($f['token']);$cancel=$wpdb->get_row('SELECT payload FROM '.DB::table('outbox')." WHERE topic='partner.cancellation_requested'",ARRAY_A);$cancel=Config::open($cancel['payload']);lcheck($cancel['recipient']==='operations-partner@example.invalid'&&Core::booking($b['public_id'])['state']==='confirmed','Cancellation wish is routed to partner without auto-confirming cancellation');
 Logistics::refresh($b['public_id']);Logistics::refresh($b['public_id']);$updated=Core::snapshot(Core::booking($b['public_id']));lcheck($updated['partner_service']['points']['handover']['address']==='New test address'&&$updated['charged']===$q['charged'],'Explicit route update preserves financial amounts');
 lcheck((int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('outbox')." WHERE topic='booking.instructions_updated'")===1,'Identical repeated instruction update does not send duplicate notice');
 $profile['billing_email']='new-billing@example.invalid';Logistics::save((int)$p['id'],$profile);Logistics::refresh($b['public_id']);lcheck((int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('outbox')." WHERE topic='booking.instructions_updated'")===1,'Internal billing contact change does not send misleading travel email');
 Core::cancel($b['public_id']);lcheck($wpdb->get_var('SELECT state FROM '.DB::table('changes').' LIMIT 1')==='completed','Confirmed cancellation completes customer review case');
 lreject(function()use($b){Logistics::refresh($b['public_id']);},'booking_not_confirmed');
 file_put_contents('/tmp/vpm-booking-logistics-report.json',wp_json_encode(['count'=>count($checks),'checks'=>$checks],JSON_PRETTY_PRINT));echo count($checks)." partner logistics/document checks passed.\n";
}finally{wp_set_current_user(1);foreach($tables as $t)$wpdb->query("DELETE FROM $t");require_once ABSPATH.'wp-admin/includes/user.php';foreach($users as $id)wp_delete_user($id);}
